// Scene kit: deck.js files draw each slide with these primitives. A scene is a flat,
// ordered list of items in inch coordinates; render-pptx.js and render-html.js both
// read the same list, so the PowerPoint and HTML versions cannot drift apart.

const { STAGE, PALETTES, ROLES } = require("./tokens");

const M = STAGE.margin;
// Content box between the running head and the footer.
const AREA = { x: M, y: 1.15, w: STAGE.w - 2 * M, h: 5.45, right: STAGE.w - M, bottom: 6.6 };

class Scene {
  constructor(mode, palette) {
    this.mode = mode;
    this.P = palette[mode];
    this.items = [];
    this.refs = new Set();
  }

  // Colour tokens ("ink", "accent", ...) resolve against the slide's palette mode;
  // anything else is taken as a hex string.
  c(v) {
    if (v == null) return null;
    return this.P[v] || String(v).replace("#", "").toUpperCase();
  }

  rect(x, y, w, h, o = {}) {
    this.items.push({ t: "rect", x, y, w, h, fill: this.c(o.fill), line: this.c(o.line), lineW: o.lineW || 1, opacity: o.opacity ?? 1, dash: o.dash });
    return this;
  }

  ellipse(x, y, w, h, o = {}) {
    this.items.push({ t: "ellipse", x, y, w, h, fill: this.c(o.fill), line: this.c(o.line), lineW: o.lineW || 1, opacity: o.opacity ?? 1 });
    return this;
  }

  circle(cx, cy, r, o = {}) { return this.ellipse(cx - r, cy - r, 2 * r, 2 * r, o); }

  line(x1, y1, x2, y2, o = {}) {
    this.items.push({ t: "line", x1, y1, x2, y2, color: this.c(o.color || "rule"), w: o.w || 1, dash: o.dash || null, arrow: o.arrow || null });
    return this;
  }

  // Ring segment. Angles in degrees, clockwise, 0 = 12 o'clock. thick = ring width in inches.
  arc(cx, cy, r, start, end, o = {}) {
    this.items.push({ t: "arc", cx, cy, r, start, end, thick: o.thick || 0.2, color: this.c(o.color || "shape") });
    return this;
  }

  // Polyline / curve through points [[x,y],...]. smooth=true draws a Catmull-Rom curve.
  path(points, o = {}) {
    this.items.push({ t: "path", points, color: this.c(o.color || "shape"), w: o.w || 3, smooth: !!o.smooth, fill: this.c(o.fill), opacity: o.opacity ?? 1, dash: o.dash || null });
    return this;
  }

  // content: string (use \n for line breaks) or array of segments:
  //   "plain", { t: "text", color: "accent", font: "condBold", size: 40 }, "\n"
  text(x, y, w, h, content, o = {}) {
    const runs = normalizeRuns(content).map(r => ({ ...r, color: this.c(r.color) }));
    this.items.push({
      t: "text", x, y, w, h, runs,
      font: o.font || "body", size: o.size || 18, color: this.c(o.color || "ink"),
      align: o.align || "left", valign: o.valign || "top", lineH: o.lineH || 1.1,
      tracking: o.tracking || 0, caps: !!o.caps, italic: !!o.italic, role: o.role || "text",
    });
    return this;
  }

  // ---- Helpers for the series' recurring text roles --------------------------------
  headline(content, o = {}) {
    const { x = AREA.x, y = AREA.y, w = 9.5, h = 1.6, size = 44 } = o;
    return this.text(x, y, w, h, content, { font: "condBold", size, lineH: 1.0, color: o.color || "ink", valign: o.valign || "top", align: o.align, role: "headline" });
  }

  lead(content, o = {}) {
    const { x = AREA.x, y = 3.2, w = 7, h = 1.4, size = 22 } = o;
    return this.text(x, y, w, h, content, { font: "light", size, lineH: 1.25, color: o.color || "muted", valign: o.valign || "top", align: o.align, role: "lead" });
  }

  // A large figure. refs: source ids that back it (required; the build checks them).
  figure(value, o = {}) {
    if (!o.refs || !o.refs.length) throw new Error(`figure "${value}" has no refs`);
    o.refs.forEach(r => this.refs.add(r));
    const { x = AREA.x, y = AREA.y, w = 6, h = 2.6, size = 150 } = o;
    return this.text(x, y, w, h, value, { font: o.font || "condLight", size, lineH: 0.9, color: o.color || "accent", valign: o.valign || "top", align: o.align, role: "figure" });
  }

  // Short on-slide citation ("Gabbett, 2016"). Full references live in notes.md.
  source(content, o = {}) {
    (o.refs || []).forEach(r => this.refs.add(r));
    const { x = AREA.x, y = 6.2, w = 8, h = 0.32, size = 11 } = o;
    return this.text(x, y, w, h, content, { font: "body", size, lineH: 1.1, color: o.color || "muted", valign: o.valign || "bottom", align: o.align, role: "source" });
  }

  label(content, o = {}) {
    const { x, y, w = 3, h = 0.36, size = 13 } = o;
    return this.text(x, y, w, h, content, { font: "cond", size, lineH: 1.0, tracking: o.tracking ?? 1.5, caps: true, color: o.color || "muted", valign: o.valign || "top", align: o.align, role: "label" });
  }

  // Note a reference that backs a claim on this slide without printing a figure.
  cite(...ids) { ids.forEach(r => this.refs.add(r)); return this; }
}

// Typographic quotes: straight ' and " render poorly in the condensed cuts.
function smarten(s) {
  return s
    .replace(/(^|[\s(—–-])"/g, "$1“").replace(/"/g, "”")
    .replace(/(^|[\s(—–-])'/g, "$1‘").replace(/'/g, "’");
}

function normalizeRuns(content) {
  const arr = Array.isArray(content) ? content : [content];
  const runs = [];
  for (const seg of arr) {
    if (seg == null) continue;
    if (typeof seg === "string") runs.push({ t: smarten(seg) });
    else runs.push({ ...seg, t: smarten(String(seg.t)) });
  }
  return runs;
}

// Build a deck module into scenes. Returns { meta, slides: [{role, mode, time, notes, scene}] }.
function buildDeck(def) {
  const palette = PALETTES[def.palette];
  if (!palette) throw new Error(`${def.slug}: unknown palette "${def.palette}"`);
  if (!def.slides || def.slides.length !== 5) throw new Error(`${def.slug}: needs exactly 5 slides`);
  const slides = def.slides.map((sd, i) => {
    const role = ROLES[i];
    if (sd.role !== role.id) throw new Error(`${def.slug}: slide ${i + 1} must be "${role.id}", got "${sd.role}"`);
    const scene = new Scene(role.mode, palette);
    sd.build(scene, { AREA, STAGE, P: scene.P });
    return { role: role.id, roleName: role.name, mode: role.mode, time: sd.time, notes: sd.notes, scene };
  });
  return { meta: def, palette, slides };
}

module.exports = { Scene, buildDeck, AREA, STAGE };

