// Series spine drawn on every slide: running head, footer, and the 5-frame rail that
// marks where the talk stands. Identical position on all 200 slides.

const { STAGE } = require("./tokens");

function chrome(deck, index, scene) {
  const P = scene.P;
  const M = STAGE.margin;
  const items = [];
  const text = (x, y, w, h, t, o) => items.push({
    t: "text", x, y, w, h, runs: [{ t }], font: o.font, size: o.size, color: o.color,
    align: o.align || "left", valign: "middle", lineH: 1, tracking: o.tracking || 0, caps: !!o.caps, italic: false, role: "chrome",
  });

  text(M, 0.42, 5, 0.3, "5 Slides · 5 Minutes", { font: "cond", size: 11, color: P.muted, tracking: 2, caps: true });
  text(STAGE.w - M - 6.5, 0.42, 6.5, 0.3, deck.meta.title, { font: "cond", size: 11, color: P.muted, tracking: 1, caps: true, align: "right" });

  text(M, 6.86, 6, 0.3, "Baylor Athletics · Applied Performance", { font: "body", size: 11, color: P.muted });

  // Rail: five frames, current one filled with the accent.
  const fw = 0.34, gap = 0.08, fh = 0.06;
  const x0 = STAGE.w - M - (5 * fw + 4 * gap);
  for (let k = 0; k < 5; k++) {
    items.push({ t: "rect", x: x0 + k * (fw + gap), y: 6.98, w: fw, h: fh, fill: k === index ? P.accent : P.rule, line: null, lineW: 1, opacity: 1 });
  }
  return items;
}

module.exports = { chrome };
