// 33 · The Ministry of Presence: showing up matters more than you think, across all programs.
// Composition: hook = one word at 104pt with a narrow lead beneath; takeaway = line centered,
// question beneath; alignment = center (hook, insight and takeaway centered; light slides
// left). Problem = hairline rules; application = one "do this Monday" sentence.

const W = 13.333;

module.exports = {
  num: 33,
  slug: "the-ministry-of-presence",
  title: "The Ministry of Presence",
  category: "Leadership & Culture",
  palette: "mint",
  hero: { layout: "season-calendar-dots", concept: "A season calendar, August to April, one row per program: small dots where someone simply showed up, spread across every program. One ringed week marks the hard moment, which arrives after many ordinary visits. Illustrative, not data." },
  compose: { hook: "single-word", takeaway: "centered", align: "center" },
  oneIdea: "Athletes bring hard things to people they already know. Being known comes from showing up, often and across every program, before anyone needs you.",
  question: "Which program here hasn't seen any of us this semester?",
  caveats: `"Ministry of presence" is Eric's phrase for a working habit: being around all programs consistently, not only the ones we already serve. Many will know it from chaplaincy; here it carries no religious meaning and asks nothing of anyone's faith. Keep it that way in the room.

The evidence is supportive, not a trial of "presence." Gulliver et al. is a small qualitative study (15 young elite athletes in Australia, three focus groups). Reis et al. are laboratory experiments with strangers, showing that more interaction led to more liking. Rebelo et al. is a narrative review summarizing qualitative work on honest self-reporting. Together they make a plausible case, not a measured effect, and the calendar on slide 3 is illustrative. Presence is not a clinical service: anything clinical goes to Baylor's licensed mental health staff.`,
  sources: [
    { id: "gulliver2012", cite: "Gulliver A, Griffiths KM, Christensen H. Barriers and facilitators to mental health help-seeking for young elite athletes: a qualitative study. BMC Psychiatry. 2012;12:157. doi:10.1186/1471-244X-12-157", grade: "qualitative focus-group study (15 elite athletes aged 16-23)", found: "external", supports: "Facilitators of help-seeking included encouragement from others, an established relationship with a provider, pleasant previous interactions with providers, and the positive attitudes of others, especially the coach." },
    { id: "rebelo2026", cite: "Rebelo A, Bishop C, Thorpe RT, Turner AN, Gabbett TJ. Monitoring training effects in athletes: a multidimensional framework for decision-making. Sports Med. 2026;56(7):1603-1624. doi:10.1007/s40279-026-02417-4", grade: "narrative review", found: "Zotero", supports: "p. 1612: athletes may under-report fatigue or soreness when they perceive a lack of trust or fear repercussions; willingness to report honestly depends on interpersonal factors; subjective monitoring is 'a socially mediated process embedded within coach-athlete and practitioner-athlete relationships.'" },
    { id: "reis2011", cite: "Reis HT, Maniaci MR, Caprariello PA, Eastwick PW, Finkel EJ. Familiarity does indeed promote attraction in live interaction. J Pers Soc Psychol. 2011;101(3):557-570. doi:10.1037/a0022885", grade: "two laboratory experiments", found: "external", supports: "The more two unacquainted people interacted, the more they liked each other, through perceived responsiveness, comfort during interaction, and knowing each other better." },
  ],
  slides: [
    {
      role: "hook", time: 45,
      notes: `One word today. Presence.

I call it a ministry of presence. You may know the phrase from chaplaincy; here it just means a habit. Showing up for a program when nothing on the schedule needs you there: a practice, a lift, a home match that isn't yours. And doing it across every program, not only the ones we already work with most.

It sounds soft. I want to show you why it isn't.`,
      build(s) {
        s.headline("Presence.", { x: 0.75, y: 1.75, w: W - 1.5, h: 1.75, size: 104, align: "center" });
        s.lead("Showing up again and again, for every program, when nothing on the schedule needs you there.", { x: (W - 6.2) / 2, y: 3.85, w: 6.2, h: 1.75, size: 24, align: "center" });
      },
    },
    {
      role: "problem", time: 60,
      notes: `Here's why it matters. When an athlete is struggling, they rarely walk into an office of a stranger. In focus groups with young elite athletes, one of the things that made it easier to ask for help was already having a relationship with the person, and having had good interactions with them before. Small study, but it matches what most of us have seen.

The same thing shows up in our data. A recent review of athlete monitoring points out that athletes under-report fatigue and soreness when they don't trust what will happen with their answers. Our wellness numbers are only as honest as our relationships.`,
      build(s) {
        s.headline("Athletes bring hard things to people they already know.", { y: 1.2, w: 11.6, h: 0.85, size: 44 });
        const rows = [
          ["Asking for help is easier with an established relationship.", "Gulliver et al. 2012 · focus groups"],
          ["Athletes under-report on wellness checks when trust is missing.", "Rebelo et al. 2026 · review"],
        ];
        rows.forEach(([t, src], i) => {
          const y = 2.75 + i * 1.6;
          s.line(0.75, y, 12.58, y, { color: "rule", w: 1 });
          s.text(0.75, y + 0.28, 8.6, 1.1, t, { font: "light", size: 28, lineH: 1.12 });
          s.source(src, { x: 9.7, y: y + 0.36, w: 2.88, h: 0.7, size: 14, align: "right", valign: "top", refs: [i ? "rebelo2026" : "gulliver2012"] });
        });
        s.line(0.75, 5.95, 12.58, 5.95, { color: "rule", w: 1 });
      },
    },
    {
      role: "insight", time: 70,
      notes: `This is what presence looks like over a season. Each row is a program; each small dot is a week someone from our staff simply showed up. No meeting, no presentation. Nothing dramatic about any single dot.

Now look at the ringed week. That's the week an athlete has something hard to say. If you've been one of those dots, you're a familiar face by then. Lab studies with strangers find that the more people interact, the more they like and trust each other, mostly because they come to feel known and comfortable.

The calendar is illustrative, not our data. The point is the pattern: many ordinary weeks first, then the one that matters.`,
      build(s) {
        s.headline("Trust gets built in ordinary weeks.", { x: 0.75, y: 1.2, w: W - 1.5, h: 0.75, size: 40, align: "center" });
        const months = ["Aug", "Sep", "Oct", "Nov", "Dec", "Jan", "Feb", "Mar", "Apr"];
        const rowsN = 6, cols = 36;
        const x0 = 2.35, cw = 0.25, y0 = 2.75, rh = 0.5;
        months.forEach((m, i) => s.label(m, { x: x0 + i * 4 * cw, y: y0 - 0.55, w: 1.0, size: 13 }));
        // A light, even rhythm: one visit every two to three weeks, offset per program.
        const visit = (r, c) => ((c * 7 + r * 5) % 17) < 7;
        for (let r = 0; r < rowsN; r++) {
          const cy = y0 + r * rh + 0.1;
          s.label(`Program ${String.fromCharCode(65 + r)}`, { x: 0.75, y: cy - 0.13, w: 1.4, h: 0.28, size: 13 });
          for (let c = 0; c < cols; c++) {
            const cx = x0 + c * cw + 0.06;
            if (visit(r, c)) s.circle(cx, cy, 0.065, { fill: "shape" });
            else s.circle(cx, cy, 0.022, { fill: "rule" });
          }
        }
        const hr = 3, hc = 25;
        s.circle(x0 + hc * cw + 0.06, y0 + hr * rh + 0.1, 0.17, { line: "accent", lineW: 2.25 });
        s.text(x0 + hc * cw + 0.3, y0 + rowsN * rh + 0.05, 3.2, 0.4, "The week it matters", { font: "cond", size: 18, color: "accent" });
        s.line(x0 + hc * cw + 0.06, y0 + hr * rh + 0.29, x0 + hc * cw + 0.06, y0 + rowsN * rh + 0.2, { color: "accent", w: 1 });
        s.text(0.75, 5.95, 5, 0.32, "Illustrative calendar, not data", { font: "light", size: 13, color: "muted" });
        s.source("Familiarity and liking: Reis et al., J Pers Soc Psychol, 2011", { x: W - 0.75 - 7, y: 5.95, w: 7, align: "right", refs: ["reis2011"] });
      },
    },
    {
      role: "application", time: 65,
      notes: `So here's the ask, and it's small on purpose.

This week, go to one practice that isn't yours. A program you don't usually serve. Stay about fifteen minutes. That number is mine, not a research finding; the point is that it's short enough to actually do.

No agenda, no clipboard, nothing to pitch. Learn two names. Then do it again in a couple of weeks. That's the whole program. It costs us nothing but a little time, and it's the thing that makes every other piece of education we do land.`,
      build(s) {
        s.headline("This week, go to one practice that isn’t yours.", { y: 2.1, w: 9.6, h: 1.8, size: 52 });
        s.lead("Stay fifteen minutes. No agenda, no clipboard. Learn two names.", { y: 4.3, w: 8.4, h: 1.0, size: 26 });
      },
    },
    {
      role: "takeaway", time: 45,
      notes: `The line to take away: be known before you're needed.

And the question for the room, which is really a question about us: which program here hasn't seen any of us this semester? Be honest. Then let's split them up before we leave. And remember the limit: presence opens the door, and anything clinical goes to our licensed mental health staff.`,
      build(s) {
        s.headline("Be known before you’re needed.", { x: 0.75, y: 1.9, w: W - 1.5, h: 1.4, size: 80, align: "center" });
        s.line(W / 2 - 0.5, 3.75, W / 2 + 0.5, 3.75, { color: "rule", w: 1.5 });
        s.text((W - 9) / 2, 4.15, 9, 1.2, "Which program here hasn’t seen any of us this semester?", { font: "medium", size: 30, color: "accent", lineH: 1.15, align: "center" });
      },
    },
  ],
};

